pragma solidity ^0.4.19;

contract PrivateDeposit
{
mapping (address => uint) public balances;

uint public MinDeposit = 1 ether;
address public owner;

Log TransferLog;

modifier onlyOwner() {
require(tx.origin == owner);
_;
}

function PrivateDeposit()
{
